def chain_fill(inp,seedcells,fillcol,allow_seed):
    h,w=len(inp),len(inp[0])
    base=[(y-seedcells[0][0],x-seedcells[0][1]) for y,x in seedcells]
    def ok(cells):
        for a,b in cells:
