    U=set(seedcells)
    changed=True
    while changed:
        changed=False
        for dy in range(-h,h):
            for dx in range(-w,w):
                cells={(y+dy,x+dx) for y,x in shape}
                if cells<=allowed and (cells & U) and not cells<=U:
