def transform(grid):
    h,w=len(grid),len(grid[0])
    cols={}
    for i in range(h):
        for j in range(w):
            cols.setdefault(grid[i][j],[]).append((i,j))
    fillcol=max((c for c in cols if c!=0), key=lambda c:len(cols[c])) if False else None
    # fill color = the color with fewest cells among nonzero? seed is small minority
    nonzero=[(c,len(cols[c])) for c in cols if c!=0]
    fillcol=min(nonzero,key=lambda t:t[1])[0]
    shape=[(y-cols[fillcol][0][0],x-cols[fillcol][0][1]) for y,x in cols[fillcol]]
    zeros={(i,j) for i in range(h) for j in range(w) if grid[i][j]==0}
    out=[row[:] for row in grid]
    for dy in range(-h,h):
        for dx in range(-w,w):
            cells={(y+dy,x+dx) for y,x in shape}
            if cells<=zeros:
                for a,b in cells: out[a][b]=fillcol
    return out
